import{_ as l,o as t,c as i,a2 as e}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"8. 连锁采集","description":"","frontmatter":{},"headers":[],"relativePath":"harvest.md","filePath":"harvest.md"}'),r={name:"harvest.md"};function s(o,a,n,h,d,c){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="_8-连锁采集" tabindex="-1">8. 连锁采集 <a class="header-anchor" href="#_8-连锁采集" aria-label="Permalink to &quot;8. 连锁采集&quot;">​</a></h1><h2 id="_8-1-触发方式" tabindex="-1">8.1 触发方式 <a class="header-anchor" href="#_8-1-触发方式" aria-label="Permalink to &quot;8.1 触发方式&quot;">​</a></h2><p><strong>潜行（Shift）+ 主手拿有效工具 + 破坏方块</strong>。</p><ul><li>只对生存模式生效；创造模式不触发。</li><li>所有世界默认启用。</li><li>工具必须是斧、镐、锄（或服务器定义的自定义工具）。</li><li>不潜行时走原版单方块破坏。</li></ul><h2 id="_8-2-三类采集" tabindex="-1">8.2 三类采集 <a class="header-anchor" href="#_8-2-三类采集" aria-label="Permalink to &quot;8.2 三类采集&quot;">​</a></h2><h3 id="砍树-斧" tabindex="-1">砍树（斧） <a class="header-anchor" href="#砍树-斧" aria-label="Permalink to &quot;砍树（斧）&quot;">​</a></h3><ul><li>只识别真正的原木/菌柄一类方块，不会把整片森林连掉。</li><li><strong>第一次尝试会被取消并提示</strong>；在 5 秒内再次破坏<strong>同一个起始方块</strong>、且仍手持原工具，才算确认。这是防误触设计。</li><li>砍伐速度按斧材质：木斧 20 原木/秒，石斧 27.5，金/铁 35，钻石 50，下界合金 60；效率附魔每级 +10%，最多计 5 级。</li><li>会消耗工具耐久；工具不会因连锁而碎掉（保留 1 点耐久）。</li><li>原木数量多时会扣食物（每 500 原木 1 点，最多 8 点，且不会把饥饿值扣到 6 以下）。</li><li>采集结束后有冷却：10–120 秒，按原木数量计算。</li></ul><h3 id="挖矿-镐" tabindex="-1">挖矿（镐） <a class="header-anchor" href="#挖矿-镐" aria-label="Permalink to &quot;挖矿（镐）&quot;">​</a></h3><ul><li>以起始矿石为中心，<strong>半径 8 格</strong>（三维切比雪夫距离），最多 <strong>64 块</strong>。</li><li>只连锁<strong>同一种矿</strong>（含深层变体），例如煤矿只连煤矿，不会顺带挖钻石。</li><li>连通方式为 26 邻接（含斜角）；不同矿种之间不会通过石头“搭桥”。</li><li>不扣食物，无额外冷却；按正常挖矿消耗耐久。</li></ul><h3 id="收作物-锄" tabindex="-1">收作物（锄） <a class="header-anchor" href="#收作物-锄" aria-label="Permalink to &quot;收作物（锄）&quot;">​</a></h3><ul><li>水平半径 <strong>6 格</strong>，最多 <strong>81 株</strong>。</li><li>只收<strong>成熟</strong>作物；未成熟、空气、水渠、瓜茎不会连接。</li><li>相邻种植面高差不超过 1 格。</li><li>默认<strong>不补种</strong>，只掉落收获物；需要补种请手动。</li><li>按正常收割消耗耐久，无额外冷却。</li></ul><h2 id="_8-3-状态查询" tabindex="-1">8.3 状态查询 <a class="header-anchor" href="#_8-3-状态查询" aria-label="Permalink to &quot;8.3 状态查询&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/harvest status       查看当前任务状态</span></span></code></pre></div><p>当前版本没有玩家可用的“取消任务”命令；任务提交后会继续完成并交付。若状态长时间不动，记录时间与坐标后联系管理组。</p><h2 id="_8-4-注意事项" tabindex="-1">8.4 注意事项 <a class="header-anchor" href="#_8-4-注意事项" aria-label="Permalink to &quot;8.4 注意事项&quot;">​</a></h2><ul><li>连锁采集有全局并发限制，人多时可能排队；排队超时会自动取消，不扣费。</li><li>不要在领地边界上故意用连锁采集“越界”挖别人领地；保护判定仍会拦截。</li><li>砍树确认机制意味着：第一下不会破坏方块，只取消并提示；第二下才真正开始连锁。不习惯时容易以为没生效。</li></ul>',16)])])}const p=l(r,[["render",s]]);export{_ as __pageData,p as default};
